def path_cells(seed, k, h, w):
    r,c = seed
    steps = k+2 if k <= 2 else k
    if k==1: dirs=[(0,1),(0,1),(-1,0)]
    elif k==2: dirs=[(0,-1)]*steps
    elif k==3: dirs=[(1,0)]*steps
    elif k==4: dirs=[(1,-1)]*steps
    elif k==6: dirs=[(-1,0)]*steps
    cells=[(r,c)]
    for dr,dc in dirs:
        r,c=r+dr,c+dc
        if not(0<=r<h and 0<=c<w): break
        cells.append((r,c))
    return cells

def transform(g):
    h,w=len(g),len(g[0])
    seeds=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]]
    out=[[0]*w for _ in range(h)]
    paths={}
    for r,c,k in seeds:
        paths.setdefault(k,[]).append(path_cells((r,c),k,h,w))
    for k,ps in paths.items():
        for cells in ps:
            for i,(r,c) in enumerate(cells):
                out[r][c] = k if i in (0,len(cells)-1) else 5
    # crossings
    from collections import Counter
    cnt=Counter()
    for k,ps in paths.items():
        for cells in ps:
            for cell in cells: cnt[cell]+=1
    cross={cell for cell,n in cnt.items() if n>1}
    for r,c in cross:
        out[r][c]=4
        r0,c0=r,c
        for _ in range(4):
            r0,c0=r0+1,c0-1
            if not(0<=r0<h and 0<=c0<w): break
            out[r0][c0]=4
    return out

